SELECT "LOGIN_ID"::text FROM "AUTH_LOGIN" WHERE "CURRENT_REFRESH_HASH" = #{hash}
UNION ALL
SELECT "LOGIN_ID"::text FROM "AUTH_REFRESH_HISTORY" WHERE "TOKEN_HASH" = #{hash}
LIMIT 1

