UPDATE "AUTH_USER_GUARD" SET "BLOCKED" = (#{operationId,jdbcType=VARCHAR} IS NOT NULL)
    , "OPERATION_ID" = #{operationId,jdbcType=VARCHAR}::uuid, "UPDATED_AT" = to_timestamp(#{now} / 1000.0)
WHERE "USER_ID" = #{userId}
